<script setup lang="ts">import{onMounted}from'vue';import{useAppStore}from'./store';import{useThemeStore,type ThemeMode}from'./themeStore';import QSidebarLayout from'../design-system/layouts/QSidebarLayout.vue';import QToast from'../design-system/components/QToast.vue';const app=useAppStore();const theme=useThemeStore();onMounted(()=>theme.set(theme.mode));const modes:ThemeMode[]=['system','light','dark']</script>
<template><QSidebarLayout><div class="q-topbar"><div><strong>{{($route.meta.title as string)||'QingToolbox'}}</strong><span class="environment-chip">Development</span></div><div class="topbar-actions"><span class="bridge-dot" :class="{connected:app.bridge==='Connected'}">{{app.bridge}}</span><div class="theme-switch" aria-label="Theme preview"><button v-for="mode in modes" :key="mode" :class="{active:theme.mode===mode}" @click="theme.set(mode)">{{mode}}</button></div></div></div><router-view/></QSidebarLayout><QToast/></template>
